mkitem!{mkenum!{# [doc = " Indicates whether a value is available or if the current task has been"] # [doc = " scheduled to receive a wakeup instead."] # [doc = ""] # [doc = " This is returned by [`Future::poll`](core::future::Future::poll)."] # [must_use = "this `Poll` may be a `Pending` variant, which should be handled"] # [derive (Copy , Clone , Debug , Eq , PartialEq , Ord , PartialOrd , Hash)] # [lang = "Poll"] # [stable (feature = "futures_api" , since = "1.36.0")] pub enum Poll < T > { # [doc = " Represents that a value is immediately ready."] # [lang = "Ready"] # [stable (feature = "futures_api" , since = "1.36.0")] Ready (# [stable (feature = "futures_api" , since = "1.36.0")] T) , # [doc = " Represents that a value is not ready yet."] # [doc = ""] # [doc = " When a function returns `Pending`, the function *must* also"] # [doc = " ensure that the current task is scheduled to be awoken when"] # [doc = " progress can be made."] # [lang = "Pending"] # [stable (feature = "futures_api" , since = "1.36.0")] Pending , }}}
mkitem!{mkimpl!{impl < T > Poll < T > { # [doc = " Maps a `Poll<T>` to `Poll<U>` by applying a function to a contained value."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " Converts a <code>Poll<[String]></code> into a <code>Poll<[usize]></code>, consuming"] # [doc = " the original:"] # [doc = ""] # [doc = " [String]: ../../std/string/struct.String.html \"String\""] # [doc = " ```"] # [doc = " # use core::task::Poll;"] # [doc = " let poll_some_string = Poll::Ready(String::from(\"Hello, World!\"));"] # [doc = " // `Poll::map` takes self *by value*, consuming `poll_some_string`"] # [doc = " let poll_some_len = poll_some_string.map(|s| s.len());"] # [doc = ""] # [doc = " assert_eq!(poll_some_len, Poll::Ready(13));"] # [doc = " ```"] # [stable (feature = "futures_api" , since = "1.36.0")] # [inline] pub fn map < U , F > (self , f : F) -> Poll < U > where F : FnOnce (T) -> U , { match self { Poll :: Ready (t) => Poll :: Ready (f (t)) , Poll :: Pending => Poll :: Pending , } } # [doc = " Returns `true` if the poll is a [`Poll::Ready`] value."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use core::task::Poll;"] # [doc = " let x: Poll<u32> = Poll::Ready(2);"] # [doc = " assert_eq!(x.is_ready(), true);"] # [doc = ""] # [doc = " let x: Poll<u32> = Poll::Pending;"] # [doc = " assert_eq!(x.is_ready(), false);"] # [doc = " ```"] # [inline] # [rustc_const_stable (feature = "const_poll" , since = "1.49.0")] # [stable (feature = "futures_api" , since = "1.36.0")] pub const fn is_ready (& self) -> bool { matches ! (* self , Poll :: Ready (_)) } # [doc = " Returns `true` if the poll is a [`Pending`] value."] # [doc = ""] # [doc = " [`Pending`]: Poll::Pending"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use core::task::Poll;"] # [doc = " let x: Poll<u32> = Poll::Ready(2);"] # [doc = " assert_eq!(x.is_pending(), false);"] # [doc = ""] # [doc = " let x: Poll<u32> = Poll::Pending;"] # [doc = " assert_eq!(x.is_pending(), true);"] # [doc = " ```"] # [inline] # [rustc_const_stable (feature = "const_poll" , since = "1.49.0")] # [stable (feature = "futures_api" , since = "1.36.0")] pub const fn is_pending (& self) -> bool { ! self . is_ready () } }}}
mkitem!{mkimpl!{impl < T , E > Poll < Result < T , E > > { # [doc = " Maps a `Poll<Result<T, E>>` to `Poll<Result<U, E>>` by applying a"] # [doc = " function to a contained `Poll::Ready(Ok)` value, leaving all other"] # [doc = " variants untouched."] # [doc = ""] # [doc = " This function can be used to compose the results of two functions."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use core::task::Poll;"] # [doc = " let res: Poll<Result<u8, _>> = Poll::Ready(\"12\".parse());"] # [doc = " let squared = res.map_ok(|n| n * n);"] # [doc = " assert_eq!(squared, Poll::Ready(Ok(144)));"] # [doc = " ```"] # [stable (feature = "futures_api" , since = "1.36.0")] # [inline] pub fn map_ok < U , F > (self , f : F) -> Poll < Result < U , E > > where F : FnOnce (T) -> U , { match self { Poll :: Ready (Ok (t)) => Poll :: Ready (Ok (f (t))) , Poll :: Ready (Err (e)) => Poll :: Ready (Err (e)) , Poll :: Pending => Poll :: Pending , } } # [doc = " Maps a `Poll::Ready<Result<T, E>>` to `Poll::Ready<Result<T, U>>` by"] # [doc = " applying a function to a contained `Poll::Ready(Err)` value, leaving all other"] # [doc = " variants untouched."] # [doc = ""] # [doc = " This function can be used to pass through a successful result while handling"] # [doc = " an error."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use core::task::Poll;"] # [doc = " let res: Poll<Result<u8, _>> = Poll::Ready(\"oops\".parse());"] # [doc = " let res = res.map_err(|_| 0_u8);"] # [doc = " assert_eq!(res, Poll::Ready(Err(0)));"] # [doc = " ```"] # [stable (feature = "futures_api" , since = "1.36.0")] # [inline] pub fn map_err < U , F > (self , f : F) -> Poll < Result < T , U > > where F : FnOnce (E) -> U , { match self { Poll :: Ready (Ok (t)) => Poll :: Ready (Ok (t)) , Poll :: Ready (Err (e)) => Poll :: Ready (Err (f (e))) , Poll :: Pending => Poll :: Pending , } } }}}
mkitem!{mkimpl!{impl < T , E > Poll < Option < Result < T , E > > > { # [doc = " Maps a `Poll<Option<Result<T, E>>>` to `Poll<Option<Result<U, E>>>` by"] # [doc = " applying a function to a contained `Poll::Ready(Some(Ok))` value,"] # [doc = " leaving all other variants untouched."] # [doc = ""] # [doc = " This function can be used to compose the results of two functions."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use core::task::Poll;"] # [doc = " let res: Poll<Option<Result<u8, _>>> = Poll::Ready(Some(\"12\".parse()));"] # [doc = " let squared = res.map_ok(|n| n * n);"] # [doc = " assert_eq!(squared, Poll::Ready(Some(Ok(144))));"] # [doc = " ```"] # [stable (feature = "poll_map" , since = "1.51.0")] # [inline] pub fn map_ok < U , F > (self , f : F) -> Poll < Option < Result < U , E > > > where F : FnOnce (T) -> U , { match self { Poll :: Ready (Some (Ok (t))) => Poll :: Ready (Some (Ok (f (t)))) , Poll :: Ready (Some (Err (e))) => Poll :: Ready (Some (Err (e))) , Poll :: Ready (None) => Poll :: Ready (None) , Poll :: Pending => Poll :: Pending , } } # [doc = " Maps a `Poll::Ready<Option<Result<T, E>>>` to"] # [doc = " `Poll::Ready<Option<Result<T, F>>>` by applying a function to a"] # [doc = " contained `Poll::Ready(Some(Err))` value, leaving all other variants"] # [doc = " untouched."] # [doc = ""] # [doc = " This function can be used to pass through a successful result while handling"] # [doc = " an error."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```"] # [doc = " # use core::task::Poll;"] # [doc = " let res: Poll<Option<Result<u8, _>>> = Poll::Ready(Some(\"oops\".parse()));"] # [doc = " let res = res.map_err(|_| 0_u8);"] # [doc = " assert_eq!(res, Poll::Ready(Some(Err(0))));"] # [doc = " ```"] # [stable (feature = "poll_map" , since = "1.51.0")] # [inline] pub fn map_err < U , F > (self , f : F) -> Poll < Option < Result < T , U > > > where F : FnOnce (E) -> U , { match self { Poll :: Ready (Some (Ok (t))) => Poll :: Ready (Some (Ok (t))) , Poll :: Ready (Some (Err (e))) => Poll :: Ready (Some (Err (f (e)))) , Poll :: Ready (None) => Poll :: Ready (None) , Poll :: Pending => Poll :: Pending , } } }}}
